import csv
from datetime import datetime, timedelta

# Decision rules: for each rule_id, map fact name to (document, field)
RULES = {
    "lca.wage_105": {
        "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM"),
        "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE"),
    },
    "lca.three_years": {
        "begin date": ("lca_disclosure", "BEGIN_DATE"),
        "end date": ("lca_disclosure", "END_DATE"),
    },
}

# Facts that are stored as Excel serial dates and must be converted
DATE_FACTS = {"begin date", "end date"}


def excel_serial_to_date(serial_str):
    """Convert an Excel serial date number to a YYYY-MM-DD string."""
    try:
        serial = int(float(serial_str))
    except (ValueError, TypeError):
        return None
    # Excel epoch for dates after 1900-03-01 is 1899-12-30
    try:
        dt = datetime(1899, 12, 30) + timedelta(days=serial)
        return dt.strftime("%Y-%m-%d")
    except OverflowError:
        return None


def load_document(packet_dir, doc_name):
    """Load a CSV document and return a dict mapping CASE_NUMBER to a list of row dicts."""
    file_path = os.path.join(packet_dir, doc_name + ".csv")
    if not os.path.exists(file_path):
        return {}
    rows_by_case = {}
    with open(file_path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            case = row.get("CASE_NUMBER")
            if case:
                case = case.strip()
                rows_by_case.setdefault(case, []).append(row)
    return rows_by_case


def get_fact_value(packet_dir, doc_cache, entity, doc_name, field, is_date):
    """Extract the value for a single fact from the appropriate document."""
    if doc_name not in doc_cache:
        doc_cache[doc_name] = load_document(packet_dir, doc_name)
    rows = doc_cache[doc_name].get(entity, [])
    values = []
    for row in rows:
        val = row.get(field)
        if val is None:
            continue
        val = val.strip()
        if val == "":
            continue
        if is_date:
            converted = excel_serial_to_date(val)
            if converted is not None:
                values.append(converted)
        else:
            values.append(val)
    if not values:
        return "ABSENT"
    if len(set(values)) == 1:
        return [values[0], doc_name]
    return "CONFLICT"


def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]
    doc_cache = {}
    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        fact_names = facts_by_rule[rule_id]
        fact_results = {}
        for fact_name in fact_names:
            doc_name, field = RULES[rule_id][fact_name]
            is_date = fact_name in DATE_FACTS
            result = get_fact_value(packet_dir, doc_cache, entity, doc_name, field, is_date)
            fact_results[fact_name] = result
        output[pair] = fact_results

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
